-- Commission Art Supabase setup and starter data. Keep the service-role key server-side only.
create table if not exists public.users (id text primary key, name text, email text unique, password text, role text, avatar text default '', bio text default '');
create table if not exists public.services (id text primary key, data text not null);
create table if not exists public.portfolio (id text primary key, data text not null);
create table if not exists public.orders (id text primary key, user_id text, data text not null);
create table if not exists public.messages (id bigint generated by default as identity primary key, order_id text, user_id text, sender text, text text, attachment text default '', created_at bigint);
create table if not exists public.reviews (id text primary key, user_id text, data text not null);
create table if not exists public.coupons (id text primary key, code text, discount numeric, active boolean default true);
create table if not exists public.sessions (token text primary key, user_id text, created_at bigint);
create table if not exists public.settings (id text primary key, data text not null);
create index if not exists orders_user_id_idx on public.orders(user_id);
create index if not exists messages_order_id_idx on public.messages(order_id);


-- Storage buckets used by the app. The portfolio bucket is public for catalog/portfolio images;
-- commission-private holds payment proofs, client references, chat attachments and delivered files.
values ('portfolio', 'portfolio', true, 15728640)
on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit;
values ('commission-private', 'commission-private', false, 15728640)
on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit;
